import { readFile, writeFile } from "fs/promises"
import path from "path"
import { NextResponse } from "next/server"

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url)
    const personaId = searchParams.get("personaId")

    if (!personaId) {
        return NextResponse.json({ error: "Missing personaId" }, { status: 400 })
    }

    // Safety check
    if (personaId.includes("..") || personaId.includes("/") || personaId.includes("\\")) {
        return NextResponse.json({ error: "Invalid personaId" }, { status: 400 })
    }

    try {
        const filePath = path.join(process.cwd(), "data", "knowledge", `${personaId}.md`)
        const content = await readFile(filePath, "utf-8")
        return NextResponse.json({ content })
    } catch (error) {
        console.warn(`Could not read file for ${personaId}`, error)
        return NextResponse.json({ content: "" }) // Return empty string if file doesn't exist yet
    }
}

export async function POST(request: Request) {
    try {
        const body = await request.json()
        const { personaId, content, password } = body

        // Debugging logs
        if (!process.env.ADMIN_PASSWORD) {
            console.error("ADMIN_PASSWORD environment variable is not set!")
        }

        if (password !== process.env.ADMIN_PASSWORD) {
            console.warn(`Admin login failed. Provided: '${password}', Expected: '${process.env.ADMIN_PASSWORD}' (Check .env.local and RESTART SERVER)`)
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
        }

        if (!personaId || typeof content !== "string") {
            return NextResponse.json({ error: "Invalid payload" }, { status: 400 })
        }

        // Safety check
        if (personaId.includes("..") || personaId.includes("/") || personaId.includes("\\")) {
            return NextResponse.json({ error: "Invalid personaId" }, { status: 400 })
        }

        const filePath = path.join(process.cwd(), "data", "knowledge", `${personaId}.md`)
        await writeFile(filePath, content, "utf-8")

        return NextResponse.json({ success: true })

    } catch (error) {
        console.error("Error writing knowledge file:", error)
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 })
    }
}
